def merge_intervals(intervals: list) -> list:
    """Merge overlapping closed integer intervals given as [start, end] lists.

    The input may be unsorted. Intervals that share at least one integer
    (e.g. [1, 3] and [3, 5], which both contain 3) are merged. Returns the
    merged intervals sorted by their start value.
    """
    if not intervals:
        return []

    cleaned = []
    for interval in intervals:
        if len(interval) != 2:
            raise ValueError(f"Interval must have exactly two elements: {interval!r}")
        start, end = interval
        if start > end:
            raise ValueError(f"Interval start must not exceed end: {interval!r}")
        cleaned.append((start, end))

    cleaned.sort(key=lambda iv: (iv[0], iv[1]))

    merged = [list(cleaned[0])]
    for start, end in cleaned[1:]:
        last = merged[-1]
        if start <= last[1]:          # overlapping or touching (closed intervals)
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged
```

