def has_cycle(graph: dict) -> bool:
    WHITE, GRAY, BLACK = 0, 1, 2
    state = {}

    def dfs(node):
        state[node] = GRAY
        for neighbor in graph.get(node, []):
            if state.get(neighbor, WHITE) == GRAY:
                return True
            if state.get(neighbor, WHITE) == WHITE and dfs(neighbor):
                return True
        state[node] = BLACK
        return False

    for node in graph:
        if state.get(node, WHITE) == WHITE and dfs(node):
            return True
    return False
