def flatten(xs, depth: int) -> list:
    """Flatten nested lists in `xs` to exactly `depth` levels of nesting.

    depth=0 leaves the structure untouched, depth=1 collapses one level of
    nesting, depth=2 two levels, and so on. Non-list elements are kept as-is.
    A new list is always returned.
    """
    if depth <= 0:
        return list(xs)

    flat = []
    for item in xs:
        if isinstance(item, list):
            flat.extend(flatten(item, depth - 1))
        else:
            flat.append(item)
    return flat
```

