def flatten(xs: list, depth: int) -> list:
    """Flatten nested lists in ``xs`` to exactly ``depth`` levels.

    ``depth = 0`` leaves the structure unchanged (returns a new list),
    ``depth = 1`` collapses one nesting level, and so on. Non-list
    elements are kept as they are.
    """
    if not isinstance(xs, list):
        raise TypeError("xs must be a list")
    if not isinstance(depth, int) or isinstance(depth, bool):
        raise TypeError("depth must be an int")
    if depth < 0:
        raise ValueError("depth must be non-negative")

    result = []
    for item in xs:
        if isinstance(item, list) and depth > 0:
            result.extend(flatten(item, depth - 1))
        else:
            result.append(item)
    return result
